import pyomo.environ as pyo

DATA = {
    "aircraft": ["aircraft_0", "aircraft_1", "aircraft_2", "aircraft_3"],
    "earliest": {
        "aircraft_0": 0,
        "aircraft_1": 7,
        "aircraft_2": 225,
        "aircraft_3": 119,
    },
    "latest": {
        "aircraft_0": 37,
        "aircraft_1": 67,
        "aircraft_2": 285,
        "aircraft_3": 179,
    },
    "early_penalty": {
        "aircraft_0": 61,
        "aircraft_1": 35,
        "aircraft_2": 74,
        "aircraft_3": 93,
    },
    "late_penalty": {
        "aircraft_0": 82,
        "aircraft_1": 34,
        "aircraft_2": 41,
        "aircraft_3": 56,
    },
    # Separation coefficients: sep[(i,j)] = required minutes if i lands before j.
    # For pair (i,j) with i<j we store forward (i before j) and backward (j before i).
    "sep_forward": {
        ("aircraft_0", "aircraft_1"): 2,
        ("aircraft_0", "aircraft_2"): 30,
        ("aircraft_0", "aircraft_3"): 30,
        ("aircraft_1", "aircraft_2"): 30,
        ("aircraft_1", "aircraft_3"): 30,
        ("aircraft_2", "aircraft_3"): 30,
    },
    "sep_backward": {
        ("aircraft_0", "aircraft_1"): 30,
        ("aircraft_0", "aircraft_2"): 2,
        ("aircraft_0", "aircraft_3"): 2,
        ("aircraft_1", "aircraft_2"): 2,
        ("aircraft_1", "aircraft_3"): 2,
        ("aircraft_2", "aircraft_3"): 2,
    },
    "big_m": 1000,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    aircraft = d["aircraft"]

    # Ordered pairs (i, j) with i < j
    pairs = []
    for a in range(len(aircraft)):
        for b in range(a + 1, len(aircraft)):
            pairs.append((aircraft[a], aircraft[b]))

    model.I = pyo.Set(initialize=aircraft, ordered=True)
    model.P = pyo.Set(initialize=pairs, dimen=2)

    # Landing time bounds
    def land_bounds(m, i):
        return (d["earliest"][i], d["latest"][i])

    model.land = pyo.Var(model.I, domain=pyo.NonNegativeReals, bounds=land_bounds)

    # Early / late deviation variables
    model.early = pyo.Var(model.I, domain=pyo.NonNegativeReals)
    model.late = pyo.Var(model.I, domain=pyo.NonNegativeReals)

    # Landing order binaries: 1 if i lands before j
    model.order = pyo.Var(model.P, domain=pyo.Binary)

    # Objective: minimize total weighted deviation penalty
    def obj_rule(m):
        return sum(
            d["early_penalty"][i] * m.early[i] + d["late_penalty"][i] * m.late[i]
            for i in m.I
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Deviation definition: land = earliest - early + late
    def dev_rule(m, i):
        return m.land[i] == d["earliest"][i] - m.early[i] + m.late[i]

    model.dev_def = pyo.Constraint(model.I, rule=dev_rule)

    # Separation constraints (both directions via big-M)
    def sep_fwd_rule(m, i, j):
        return m.land[j] >= (
            m.land[i]
            + d["sep_forward"][(i, j)]
            - d["big_m"] * (1 - m.order[(i, j)])
        )

    model.sep_fwd = pyo.Constraint(model.P, rule=sep_fwd_rule)

    def sep_bwd_rule(m, i, j):
        return m.land[i] >= (
            m.land[j]
            + d["sep_backward"][(i, j)]
            - d["big_m"] * m.order[(i, j)]
        )

    model.sep_bwd = pyo.Constraint(model.P, rule=sep_bwd_rule)

    return model


